import { Pencil, Trash2, Users } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/common/empty-state";
import { formatRelative } from "@/lib/utils/time";
import type { Client, Plan } from "@/lib/types";

interface ClientsTableProps {
  clients: readonly Client[];
  onClearFilters?: () => void;
}

const TOTAL_CLIENTS = 12;

const planConfig: Record<Plan, { label: string; className: string }> = {
  free: {
    label: "Free",
    className: "bg-slate-100 text-slate-600 ring-1 ring-slate-200",
  },
  starter: {
    label: "Starter",
    className: "bg-sky-100 text-sky-700 ring-1 ring-sky-200",
  },
  growth: {
    label: "Growth",
    className: "bg-primary/10 text-primary ring-1 ring-primary/20",
  },
  scale: {
    label: "Scale",
    className: "bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200",
  },
};

const mrrFormatter = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});

function getInitials(name: string): string {
  return name
    .split(" ")
    .map((n) => n[0] ?? "")
    .slice(0, 2)
    .join("")
    .toUpperCase();
}

function PlanBadge({ plan }: { plan: Plan }) {
  const config = planConfig[plan];
  return (
    <span
      className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${config.className}`}
    >
      {config.label}
    </span>
  );
}

export function ClientsTable({ clients, onClearFilters }: ClientsTableProps) {
  return (
    <Card className="overflow-hidden">
      <CardContent className="p-0">
        {clients.length === 0 ? (
          <EmptyState
            icon={Users}
            title="No matching clients"
            description="Try clearing your filters to see all clients."
            action={{ label: "Clear filters", onClick: onClearFilters }}
          />
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="pl-4 min-w-[200px]">Client</TableHead>
                  <TableHead className="hidden md:table-cell min-w-[140px]">
                    Company
                  </TableHead>
                  <TableHead>Plan</TableHead>
                  <TableHead className="text-right">Requests</TableHead>
                  <TableHead className="text-right">MRR</TableHead>
                  <TableHead className="hidden md:table-cell">Joined</TableHead>
                  <TableHead className="w-20 text-right pr-4">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {clients.map((client) => (
                  <TableRow
                    key={client.id}
                    className="cursor-pointer hover:bg-muted/30"
                    onClick={() => {
                      /* TODO(phase2): navigate to client detail */
                    }}
                  >
                    {/* Client — avatar + name + email */}
                    <TableCell className="pl-4">
                      <div className="flex items-center gap-3">
                        <Avatar className="size-8 shrink-0">
                          <AvatarImage
                            src={client.avatarUrl}
                            alt={client.name}
                          />
                          <AvatarFallback className="text-xs">
                            {getInitials(client.name)}
                          </AvatarFallback>
                        </Avatar>
                        <div className="min-w-0">
                          <p className="font-medium text-sm leading-tight truncate">
                            {client.name}
                          </p>
                          <p className="text-xs text-muted-foreground truncate">
                            {client.email}
                          </p>
                        </div>
                      </div>
                    </TableCell>

                    {/* Company — hidden on md and below */}
                    <TableCell className="hidden md:table-cell text-sm">
                      {client.company}
                    </TableCell>

                    {/* Plan */}
                    <TableCell>
                      <PlanBadge plan={client.plan} />
                    </TableCell>

                    {/* Active Requests */}
                    <TableCell className="text-right tabular-nums text-sm">
                      {client.activeRequests}
                    </TableCell>

                    {/* MRR */}
                    <TableCell className="text-right tabular-nums text-sm font-medium">
                      {client.mrr === 0
                        ? "—"
                        : `${mrrFormatter.format(client.mrr)}/mo`}
                    </TableCell>

