interface ClientsFilters {
  search: string;
  plan: Plan | "all";
}

const initial: ClientsFilters = { search: "", plan: "all" };

export default function ClientsPage() {
  const [filters, setFilters] = useState<ClientsFilters>(initial);
  const [dialogOpen, setDialogOpen] = useState(false);

  const filtered = useMemo(
    () =>
      allClients.filter((c) => {
        if (filters.plan !== "all" && c.plan !== filters.plan) return false;
        if (filters.search) {
          const q = filters.search.toLowerCase();
          if (
            !c.name.toLowerCase().includes(q) &&
            !c.company.toLowerCase().includes(q) &&
            !c.email.toLowerCase().includes(q)
          )
            return false;
        }
        return true;
      }),
    [filters],
  );

  const hasActive = filters.search !== "" || filters.plan !== "all";

  return (
    <>
      <PageHeader
        title="Clients"
        subtitle="Your active client accounts"
        actions={
          <Button onClick={() => setDialogOpen(true)}>
            <Plus className="size-4 mr-1.5" />
            New client
          </Button>
        }
      />
      <div className="space-y-4">
        <ClientsFilterBar
          filters={filters}
          onChange={setFilters}
          onClear={() => setFilters(initial)}
          hasActiveFilters={hasActive}
        />
        <ClientsTable
          clients={filtered}
          onClearFilters={() => setFilters(initial)}
        />
      </div>
      <NewClientDialog open={dialogOpen} onOpenChange={setDialogOpen} />
    </>
  );
}

