          filters={filters}
          onChange={setFilters}
          onClear={() => setFilters(initial)}
          hasActiveFilters={hasActive}
        />
        <ServicesTable
          services={filtered}
          onClearFilters={() => setFilters(initial)}
        />
      </div>
      <NewServiceDialog open={dialogOpen} onOpenChange={setDialogOpen} />
    </>
  );
}
